 * tree-render.ts — 渲染层
 *
 * 用 kfmv3 v2 引擎渲染 Box 树到 Canvas。
 * 滚动事件 → 写 rootBox.scrollY → 引擎自动处理裁剪/偏移/滚动条。
 * 点击事件 → 光标优先：第一次点击移动光标，第二次点击同一行执行 onTap。
 */

import { buildSidebarTree } from './tree-model.js';
import { KFMState, getFileRowData, type FileRowData } from './state.js';
import { anim } from './animation-registry.js';
import { setupCharRainTweens, setupCharRainForSiblings, cleanupCharRain, type CharRainCleanup } from "./char-rain.js";
import { closeSidebar } from './ui.js';
import { Renderer } from '../engine/v2/renderer.js';
import { L } from './renderer-lifecycle.js';
import { _rebuildRowIndex, findBoxById } from './canvas-utils.js';
import { Box } from '../engine/v2/box.js';
import { getCursorRowIndex, moveCursorTo, ensureCursorBox, scrollToCenterCursor } from './canvas-cursor.js';
import { initScrollGesture, bindWheelEvents } from './canvas-scroll.js';
import { DOM } from "./dom-refs.js";
import * as clickQueue from "./click-queue.js";
import { assert } from "./debug-assert.js";
import { createRootPicker, destroyRootPicker, isPickerOpen } from './root-picker.js';
import { log } from './logger.js';
import { wsChannel } from './ws-channel.js';
import { Registry } from './ui-registry.js';
import { currentTheme as theme } from './theme.js';
import {
  type OverlayMeta, type OverlayPack, type FlatSubTarget,
  removeAllOverlays, createCharLayer, collectSiblingsAfter,
  buildAndSetOverlayTree, createVisualClone,
  setupExpandOverlays, setupCollapseOverlays, collectAncestorSiblings, collectAncestorContainers,
  flattenExpandTree, ensureMetaFromExpandedState,
  activeOverlayCount,
} from './tree-overlay.js';
import { bounceCursorRow, handleRowSwipe, clearTempCards, initTempCardGesture, dismissFocusedCard } from './tree-swipe.js';
const ts = anim.scope('tree-render');
/** 重置动画时间线：清空 tween + 归零播放头 + 清除回调。正常动画结束时调用。 */
function _resetAnimTimeline(): void {
  ts.clear();
  ts.eventCallback('onComplete', null);
  ts.reversed(false);  // 清除反转状态，确保新加 tween 正向播放
  ts.time(0);
}

/** 文件路径 → Box 屏幕坐标的反向索引。rebuildTree 后自动重建。 */
interface BoxLocation {
  path: string;
  box: Box;
  rowIndex: number;
  screenRect: { x: number; y: number; width: number; height: number };
}

const _boxLocationMap: Map<string, BoxLocation> = new Map();


/** 保存 KFMState 订阅引用，防止重复订阅 */
function _ensureSubscribed(): void {
  const prev = L.getStateSub();


  if (prev) KFMState.unsubscribe(prev);
  const fn = () => {
    // state 变化（toggleHidden/expanded）是用户主动行为，跳过 isAnimating 锁
    rebuildTree();
  };
  L.setStateSub(fn);
  KFMState.subscribe(fn);
}

/** 遍历 Box 树，为每个可见文件行重建 _boxLocationMap */
function _rebuildBoxLocationMap(root: Box): void {
  _boxLocationMap.clear();
  let rowIndex = 0;
  function walk(box: Box): void {
    for (const child of box.children) {
      if (!child.visible || child.disabled) continue;
      const data = getFileRowData(child.data);
      if (data && child.gesture?.onTap) {
        const abs = child.getAbsolutePosition();
        _boxLocationMap.set(data.path, {
          path: data.path,
          box: child,
          rowIndex,
          screenRect: {
            x: abs.x,
            y: abs.y,
            width: child.width,
            height: child.height,
          },
        });
        rowIndex++;
      }
      walk(child);
    }
  }
  walk(root);
}

/** 根据文件路径返回 Box 中心坐标，不可见时返回 null */
export function locateFileBox(path: string): { x: number; y: number } | null {
  const loc = _boxLocationMap.get(path);
  if (!loc) return null;
  return {
    x: loc.screenRect.x + loc.screenRect.width / 2,
    y: loc.screenRect.y + loc.screenRect.height / 2,
  };
}

/** 通过文件路径直接触发 Canvas 文件行操作（tap），路径不可见时���默失败 */
export function executeOnPath(path: string, action: 'tap'): void {
  const loc = _boxLocationMap.get(path);
  if (!loc || action !== 'tap') return;
  loc.box.gesture?.onTap?.();
}

/** 外部使用：标记某路径正在做展开动画（懒加载专用） */
export function markAnimatingPath(path: string | null): void {
  if (path === null) {
    L.endOp();
  } else {
    L.beginOp(path, 'expand');
  }
}

/** 懒加载等场景的程序化展开入口：跳过状态切换和生命周期锁，直接跑动画 */
/** 从终端树获取展开所需的上下文（容器、三角、完整高度）。
 *  如果 fullHeight 为 0，自动处理三角旋转动画并调 onEmpty 回调。
 *  返回 null 时调用方应直接返回（无需继续）。
 *  onEmpty 用于生命周期清理（doExpand 需要 unlock，triggerExpandAnimation 不需要）。 */
function _getExpandContext(
  root: Box,
  path: string,
  onEmpty?: () => void,
): { container: Box; toggle2: Box | undefined; fullHeight: number } | null {
  const container = findBoxById(root, `expanded-${path}`);
  const titleRow = findBoxById(root, `title-${path}`);
  if (!container) { onEmpty?.(); return null; }
  const toggle2 = titleRow?.children?.find(c => c.id?.startsWith('toggle-'));

  const fullHeight = (container as Box & OverlayMeta)._fullHeight || 0;
  if (!fullHeight) {
    if (toggle2 && toggle2.transform) {
      toggle2.transform.rotate = 0;
      ts.to(toggle2.transform, {
        rotate: Math.PI / 2,
        duration: 0.3,
        ease: 'power2.out',
        onComplete: onEmpty,
      }, 0);
    } else {
      onEmpty?.();
    }
    return null;
  }
  return { container, toggle2, fullHeight };
}

export function triggerExpandAnimation(path: string): void {
  const root = L.renderer?.getRoot();
  if (!root) return;
  const ctx = _getExpandContext(root, path);
  if (!ctx) return;
  _runExpandAnimation({ container: ctx.container, root, fullHeight: ctx.fullHeight, toggle2: ctx.toggle2, path, onTap: null });
}
export function isAnimLocked(): boolean {
  return L.isAnimating;
}

// ========== 文件行右滑：回弹 + 加入临时卡片堆 ==========


// ============================================================
// 光标状态
// ============================================================

// 光标步进模式 —— 行索引（按绝对 Y 坐标排序的可交互行）

// ===== 事件堆栈 + 会话隔离 =====
// 会话隔离：每次开/关侧栏递增 L._sessionId，旧会话异步操作自动失效
// 事件堆栈：同一会话内快速点击串行执行

export function onSidebarOpen(): void {
  // ===== 销毁旧渲染器 + 通过生命周期重置所有状态 =====
  _resetAnimTimeline();
  L.renderer?.stop();
  L.renderer = null;
  L.resetForOpen();

  // ===== 从零重建：销毁旧 canvas，创建新渲染器 =====
  const fileTree = DOM.fileTree;
  if (!fileTree) return;

  const canvas = document.createElement('canvas');
  canvas.dataset.registryId = 'file-tree';
  canvas.id = 'tree-canvas';
  canvas.style.width = '100%';
  canvas.style.height = '100%';
  canvas.style.display = 'block';
  canvas.style.touchAction = 'none';

  fileTree.innerHTML = '';          // 彻底销毁旧 DOM（包括旧 canvas）
  fileTree.appendChild(canvas);

  const dpr = window.devicePixelRatio || 1;
  L.renderer = new Renderer(canvas, {
    backgroundColor: 'rgba(10,10,15,0.85)',
    dpr,
    theme: theme.canvas,
  });

  // 等 CSS layout 完成后再 rebuildTree（canvas 刚创建时 clientWidth=0）
  requestAnimationFrame(() => {
    try {
    removeAllOverlays();
    rebuildTree();
    // rebuildTree 后强制恢复 scrollY（在所有可能覆盖它的逻辑之后）
    if (L._savedScrollY > 0) {
      const root = L.renderer?.getRoot();
      if (root) {
        const maxY = root.getMaxScroll().maxY;
        root.scrollY = Math.min(L._savedScrollY, maxY);
        // 实验日志：写到页面上可见
        const savedVal = root.scrollY;
        L._savedScrollY = 0;
        L.setRestoreMode(true);
        setTimeout(() => {
          L.setRestoreMode(false);
          // 最终检查：如果 scrollY 被覆盖了，强制恢复
          const r2 = L.renderer?.getRoot();
          if (r2 && Math.abs(r2.scrollY - savedVal) > 10) {
            r2.scrollY = savedVal;
          }
          // 最终状态日志
        }, 500);
      }
    }
    L._restoringFromSave = false;
    L.renderer?.resize();

    _ensureSubscribed();
    window.addEventListener('resize', () => L.renderer?.resize());

    bindWheelEvents(canvas);
    bindClickEvents(canvas, dpr);

    // 创建左栏右侧触摸盒子
    _createSidebarTouchArea();
    } catch (e) { log('[sidebar] open crash: ' + (e instanceof Error ? e.message + ' ' + (e.stack || '') : String(e))); }
  });

  // 等侧栏 CSS 过渡结束后再 resize 一次
  const sidebar = DOM.sidebar;
  if (sidebar) {
    const onEnd = () => {
      sidebar.removeEventListener('transitionend', onEnd);
      L.renderer?.resize();
    };
    sidebar.addEventListener('transitionend', onEnd);
  }
  _createSidebarTouchArea();
  createRootPicker();
}


export function onSidebarClose(): void {
  // 幂等：侧栏已关闭时跳过（防 overlay + 关闭按钮同时触发）
  if (L.isSidebarClosed()) return;
  // 先停掉所有动画和独立rAF循环
  removeAllOverlays();
  _resetAnimTimeline();
  clearTempCards();
  L.setSidebarClosed(true);  // 让wheel/touch的rAF循环自己退出
  L.endOp();

  L._restoringFromSave = true;
  // 直接保存当前 scrollY（动画停止后的稳定值）
  const rootScrollY = L.renderer?.getRoot()?.scrollY ?? 0;
  // 关键：只有 L.renderer 存在时才保存，避免用 0/null 覆盖正确的值
  if (L.renderer && L.renderer.getRoot()) {
    L.saveSidebarScrollState(rootScrollY, L.cursorRowId);
  }
  clickQueue.clear();
  L.cursorBox = null;
  if (L.renderer) L.renderer.cursorBox = null;
  L.cursorRowId = null;
  L._rowIndex = [];
  L.renderer?.stop();
  L.renderer = null;
  DOM.sidebarTouchArea?.remove();
  destroyRootPicker();
  L.cancelAllRafs();
}

export function initTreeRenderer(): void {
  const fileTree = DOM.fileTree;
  if (!fileTree) {
    log('[warn] [tree-render] #fileTree not found');
    return;
  }

  initScrollGesture();
  initTempCardGesture();

  const canvas = document.createElement('canvas');
  canvas.dataset.registryId = 'file-tree';
  canvas.id = 'tree-canvas';
