  canvas.style.display = 'block';
  canvas.style.touchAction = 'none';

  fileTree.innerHTML = '';
  fileTree.appendChild(canvas);

  const dpr = window.devicePixelRatio || 1;
  L.renderer = new Renderer(canvas, {
    backgroundColor: 'rgba(10,10,15,0.85)',
    dpr,
    theme: theme.canvas,
  });
  rebuildTree();

  _ensureSubscribed();
  window.addEventListener('resize', () => L.renderer?.resize());

  bindWheelEvents(canvas);
  bindClickEvents(canvas, dpr);
  // 注册 UI 元素：文件树 Canvas 区域
  Registry.registerElement({
    id: 'file-tree',
    type: 'panel',
    label: '文件树',
    description: 'Canvas 自渲染文件树，点击目录展开/折叠，点击文件选中。AI 可通过 expand-dir/collapse-dir/select-file/click-path 命令操作',
    state: DOM.sidebar?.classList.contains('open') ? 'visible' : 'hidden',
    enabled: true,
    effect: '点击目录切换展开/折叠状态，点击文件将其设为选中。AI 可发送 expand-dir/collapse-dir/select-file/click-path 命令远程操作',
    source: 'tree-render.ts',
  }, () => DOM.sidebar?.classList.contains('open') ? 'visible' : 'hidden');
  // 注册 AI 指令处理器：文件树操作
  wsChannel.onCommand('expand-dir', (_action, params) => {
    const path = params.path as string;
    if (path) KFMState.setExpanded(path, true);
  });
  wsChannel.onCommand('collapse-dir', (_action, params) => {
    const path = params.path as string;
    if (path) KFMState.setExpanded(path, false);
